import {money,esc,empty} from './ui.js';
const tipAttr=s=>esc(s).replace(/\n/g,'&#10;');
export function renderTrend(series,{expectedColor='#a6b3c7',fillArea=false}={}){
 const values=series.flatMap(p=>[p.actual,p.expected]).filter(v=>Number.isFinite(v));if(!values.length)return empty('暂无可比趋势','缺少实际数据或预期基线时，不绘制利润曲线。');
 const W=800,H=330,L=64,R=25,T=20,B=42;const low=Math.min(0,...values),high=Math.max(1,...values);const span=(high-low)*1.13;const y=v=>T+(high*1.08-v)/span*(H-T-B);const x=i=>L+i*(W-L-R)/Math.max(1,series.length-1);
 let grid='';for(let i=0;i<5;i++){const v=low+(high-low)*i/4;grid+=`<line x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}" stroke="#edf1f6"/><text x="${L-12}" y="${y(v)+4}" text-anchor="end">${Math.abs(v)>=10000?(v/10000).toFixed(1)+'万':Math.round(v).toLocaleString()}</text>`;}
 const path=key=>{let pen=false;return series.map((p,i)=>{if(p[key]===null){pen=false;return '';}const s=`${pen?'L':'M'}${x(i)},${y(p[key])}`;pen=true;return s;}).join(' ');};
 const areaPath=key=>{const parts=[];let segment=[];const close=()=>{if(segment.length){parts.push(`M${segment[0].x},${y(0)} ${segment.map(p=>`L${p.x},${p.y}`).join(' ')} L${segment.at(-1).x},${y(0)} Z`);segment=[];}};series.forEach((p,i)=>{if(!Number.isFinite(p[key]))close();else segment.push({x:x(i),y:y(p[key])});});close();return parts.join(' ');};
 const areas=fillArea?`<path class="trend-area" d="${areaPath('expected')}" fill="${esc(expectedColor)}" fill-opacity=".07"/><path class="trend-area" d="${areaPath('actual')}" fill="#3274ef" fill-opacity=".10"/>`:'';
 const labels=series.map((p,i)=>i%Math.max(1,Math.ceil(series.length/8))===0||i===series.length-1?`<text x="${x(i)}" y="${H-8}" text-anchor="middle">${p.date.slice(5).replace('-','/')}</text>`:'').join('');
 const dots=series.map((p,i)=>p.actual===null?'':`<g class="chart-point" tabindex="0" role="button" data-day="${p.date}" aria-label="${p.date} 实际 ${money(p.actual,2)}，预期 ${money(p.expected,2)}" data-tip="${tipAttr(`${p.date}\n实际 ${money(p.actual,2)}\n同进度理论 ${money(p.expected,2)}${p.missing?`\n${p.missing} 笔无当日日报`:''}`)}"><circle cx="${x(i)}" cy="${y(p.actual)}" r="11" fill="transparent"/><circle cx="${x(i)}" cy="${y(p.actual)}" r="3.3" fill="#3274ef" stroke="white" stroke-width="1.5"/></g>`).join('');
 const expectedDots=series.map((p,i)=>p.expected===null?'':`<g class="trend-expected-point"><circle cx="${x(i)}" cy="${y(p.expected)}" r="9" fill="transparent" data-tip="${tipAttr(`${p.date}\n同进度理论 ${money(p.expected,2)}\n实际 ${money(p.actual,2)}`)}"/><circle cx="${x(i)}" cy="${y(p.expected)}" r="3" fill="${esc(expectedColor)}" stroke="white" stroke-width="1.2" pointer-events="none"/></g>`).join('');
 return `<svg class="trend-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="实际与同期预期生产毛利趋势；支持键盘、触摸或点击数据点查看数值"><g class="trend-area-layer">${areas}</g>${grid}<g class="trend-reveal-layer"><path d="${path('expected')}" fill="none" stroke="${esc(expectedColor)}" stroke-width="2" stroke-dasharray="5 5"/><path d="${path('actual')}" fill="none" stroke="#3274ef" stroke-width="3" stroke-linejoin="round"/>${expectedDots}${dots}</g>${labels}</svg>`;
}
export function renderCostVariance(items){const max=Math.max(1,...items.map(i=>Math.abs(i.delta??0)));return `<div class="variance-bars">${items.map(i=>`<div class="variance-row"><span>${esc(i.name)}</span><div class="bar-track"><div class="bar-fill ${i.delta>0?'red':'green'}" style="width:${Math.abs(i.delta??0)/max*100}%"></div></div><strong class="${i.delta>0?'negative':'positive'}">${i.delta===null?'—':(i.delta>0?'+':'−')+money(Math.abs(i.delta))}</strong></div>`).join('')}</div>`;}
export function renderCostDonut(items){
 const known=items.filter(i=>i.value!==null);const total=known.reduce((s,i)=>s+i.value,0);
 if(!known.length||!(total>0))return empty('暂不可拆分成本构成','实际材料或费用资料不完整时不绘制构成图，缺失项不按零处理。');
 const R=52,C=2*Math.PI*R;let offset=0;
 const arcs=known.map(i=>{const len=i.value/total*C;const share=(i.value/total*100).toFixed(1)+'%';const text=`${i.name}\n${i.display} · ${share}`;const a=`<circle class="donut-arc" cx="70" cy="70" r="${R}" fill="none" stroke="${i.color}" stroke-width="20" stroke-dasharray="${len.toFixed(2)} ${(C-len).toFixed(2)}" stroke-dashoffset="${(-offset).toFixed(2)}" transform="rotate(-90 70 70)" tabindex="0" role="img" aria-label="${esc(`${i.name} ${i.display} · ${share}`)}" data-tip="${tipAttr(text)}"/>`;offset+=len;return a;}).join('');
 const legend=items.map(i=>{const share=i.value===null?null:(i.value/total*100).toFixed(1)+'%';return `<li class="${i.value===null?'is-pending':''}" title="${esc(i.name+' '+i.display+(share?' · '+share:''))}"><i class="donut-dot" style="background:${i.value===null?'#d6deea':i.color}"></i><span class="donut-name">${esc(i.name)}<em class="donut-amount">${esc(i.value===null?'待补齐':i.display)}</em></span><b class="donut-pct">${share??'—'}</b></li>`;}).join('');
 const pending=items.some(i=>i.value===null);
 return `<div class="donut-grid"><svg class="donut" viewBox="0 0 140 140" role="img" aria-label="已归集生产及经营费用，合计 ${total.toLocaleString('zh-CN',{maximumFractionDigits:2})} 元"><circle cx="70" cy="70" r="${R}" fill="none" stroke="#f1f4f9" stroke-width="20"></circle>${arcs}<text x="70" y="64" text-anchor="middle" class="donut-label">已归集成本</text><text x="70" y="84" text-anchor="middle" class="donut-total">¥${total.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})}</text></svg><div class="donut-legend-wrap"><ul class="donut-legend">${legend}</ul>${pending?'<p class="donut-note">占比以已归集项目为基数；灰色项待补齐，不按零计。</p>':''}</div></div>`;
}
